let missFilter='All',missDisc='All',missQuery='',missHideDone=false;
function makeStables(){return Array.from({length:6},()=>({name:'',breed:'Empty',sex:'Unknown',wins:0,ready:false}));}
function missStatus(a){return a.key&&state.checks[a.key]?'done':state.missables[a.id]||'pending';}
function alertCount(ch){return ALERTS.filter(a=>a.ch===ch&&missStatus(a)==='pending').length;}
function chapterWarnings(c){const entries=ALERTS.filter(a=>a.ch===c.id&&!a.auto&&missStatus(a)==='pending');const recruits=PARTY.filter(p=>p.optional&&p.chapter===c.id&&!state.roster[p.id]);if(!entries.length&&!recruits.length)return '';return `<section class="checkpoint-panel"><div class="section-heading"><h2>Before you leave this chapter</h2><span>${entries.length} unchecked item / event reminders</span></div>${recruits.map(p=>`<div class="recruit-callout"><div><span class="eyebrow">EARLIEST RECRUITMENT</span><h3>${esc(p.name)} is available now.</h3><p>${esc(p.how)}</p></div><button class="button primary" data-quest="${p.quest}">Recruitment steps →</button></div>`).join('')}${entries.slice(0,4).map(a=>`<div class="checkpoint-line"><span class="pill ${a.risk==='Permanent'?'missable':''}">${esc(a.risk)}</span><div><b>${esc(a.name)}</b><p>${esc(a.window)}</p></div></div>`).join('')}<button class="button" data-alert-chapter="${c.id}">Review ${entries.length?'all '+entries.length:'chapter'} items & events →</button><p class="fine">These are reminders for this location, not a declaration that you have passed a deadline in your game.</p></section>`;}
function missableRows(){let rows=ALERTS.filter(a=>{const c=C.find(c=>c.id===a.ch);return (missDisc==='All'||String(c.disc)===missDisc)&&(missFilter==='All'||(missFilter==='This chapter'?a.ch===state.chapter:missFilter==='Events'?a.kind==='Event':missFilter==='Items'?a.kind==='Item'||a.kind==='Materia':a.risk===missFilter))&&(!missHideDone||missStatus(a)!=='done')&&[a.name,a.window,a.action,a.recovery,c.title].join(' ').toLowerCase().includes(missQuery.toLowerCase());});rows.sort((a,b)=>C.findIndex(c=>c.id===a.ch)-C.findIndex(c=>c.id===b.ch));return rows.length?rows.map(a=>`<article class="register-row ${missStatus(a)==='done'?'secured':''}"><div class="register-main"><div class="register-tags"><span class="pill ${a.risk==='Permanent'?'missable':''}">${esc(a.risk)}</span><span>${esc(a.kind)} · Disc ${C.find(c=>c.id===a.ch).disc}</span></div><h3>${esc(a.name)}</h3><p class="deadline"><b>Window:</b> ${esc(a.window)}</p><p>${esc(a.action)}</p>${a.recovery?`<p class="recovery"><b>Recovery / caution:</b> ${esc(a.recovery)}</p>`:''}<button class="register-chapter" data-chapter="${a.ch}">Open chapter ${a.ch.slice(1)} →</button></div><select data-miss="${a.id}" aria-label="Status: ${esc(a.name)}">${[['pending','Unchecked'],['done',a.kind==='Event'?'Seen / completed':'Secured / learned'],['missed','Missed on my save'],['skipped','Skipped intentionally']].map(([v,l])=>`<option value="${v}" ${missStatus(a)===v?'selected':''}>${l}</option>`).join('')}</select></article>`).join(''):'<div class="empty">No entries match these filters.</div>';}
function missables(){return `<div class="view-heading"><span class="eyebrow">THE COMPLETIONIST’S REGISTER</span><h1>Leave fewer things behind.</h1><p>Item locations, event windows, limited steals and one-way rewards, in story order.<br>“Window” means an opportunity has conditions or a deadline; “Recoverable” means a later fallback exists.</p></div><div class="register-overview"><div><b>${ALERTS.length}</b><small>tracked items & events</small></div><div><b id="missDone">${ALERTS.filter(a=>missStatus(a)==='done').length}</b><small>secured / completed</small></div><div><b>${ALERTS.filter(a=>a.risk==='Permanent').length}</b><small>permanent-loss warnings</small></div></div><div class="notice">Mark your actual results yourself. Browsing a later chapter never marks something missed. These pages reveal locations and game mechanics. Keep separate saves before every one-way area; this register covers named equipment, major Materia and event windows, rather than every quantity of ordinary consumables.</div><div class="toolbar"><input id="missSearch" value="${esc(missQuery)}" placeholder="Search item, enemy, event or location…" aria-label="Search items and events"><select id="missFilter" aria-label="Filter item and event type">${['All','This chapter','Permanent','Window','Recoverable','Items','Events','Optional'].map(t=>`<option ${missFilter===t?'selected':''}>${t}</option>`).join('')}</select><select id="missDisc" aria-label="Filter item and event disc">${['All','1','2','3'].map(t=>`<option value="${t}" ${missDisc===t?'selected':''}>${t==='All'?'All discs':'Disc '+t}</option>`).join('')}</select><label><input type="checkbox" id="missHideDone" ${missHideDone?'checked':''}> Hide completed</label></div><div id="missRows">${missableRows()}</div><div class="notice"><b>Fort Condor:</b> the register includes all 15 attacks you can personally play. Attacks 14–18 and 20 occur while you are elsewhere and cannot be played normally. Attack numbers follow the story schedule, not your win count. Rewards depend on wins. Earlier optional attacks are not prerequisites for the final Huge Materia defense.</div>`;}
function characters(){const count=PARTY.filter(p=>state.roster[p.id]).length;return `<div class="view-heading"><span class="eyebrow">ALL NINE PARTY MEMBERS · EARLIEST ROUTE</span><h1>No one left behind.</h1><p>Seven characters join through the story. Yuffie and Vincent need deliberate detours.<br>Recruit both at their first available point; neither requires waiting for Disc 2.</p></div><div class="journey-hero"><div><span class="eyebrow">YOUR PARTY</span><h2>${count} / 9 recruitment goals checked</h2><p>Optional characters can still be recruited later before the finale. “Optional” does not mean permanently lost at the next chapter.</p></div><button class="button" data-view="missables">Review item & event windows →</button></div><div class="party-grid">${PARTY.map((p,i)=>`<article class="card party-card"><div class="party-top"><span class="portrait-initial character-portrait portrait-${p.id}" role="img" aria-label="${esc(p.name)} portrait"></span><div><span class="eyebrow">${String(i+1).padStart(2,'0')} · ${p.optional?'OPTIONAL · RECRUIT EARLY':'STORY RECRUITMENT'}</span><h2>${esc(p.name)}</h2></div></div><h3>Earliest: ${esc(p.when)}</h3><p>${esc(p.how)}</p><p class="fine">${esc(p.role)}</p><div class="party-actions"><button class="button ${p.optional?'primary':''}" ${p.quest?'data-quest="'+p.quest+'"':'data-chapter="'+p.chapter+'"'}>${p.optional?'Exact recruitment steps':'Open story chapter'} →</button><label><input type="checkbox" data-roster="${p.id}" ${state.roster[p.id]?'checked':''}> Joined my party</label></div></article>`).join('')}</div><div class="notice"><b>Early Vincent:</b> Lost Number is the practical obstacle. Save before the safe; use status protection and a reliable healer. If you need to train, do so near Nibelheim before Mount Nibel, then return. You do not need to postpone his recruitment to the late game.</div>`;}
function breedingResult(a,b,nut){if(a===b)return {ok:false,title:'Choose two different stalls.',text:'A breeding pair requires two different Chocobos.'};const x=state.stables[a],y=state.stables[b];if(!x||!y||x.breed==='Empty'||y.breed==='Empty')return {ok:false,title:'Record both parents first.',text:'Choose occupied stalls in your stable log.'};if(x.sex==='Unknown'||y.sex==='Unknown')return {ok:false,title:'Confirm both sexes.',text:'Billy reveals sex when you move a Chocobo into a stall.'};if(x.sex===y.sex)return {ok:false,title:'The pair needs opposite sexes.',text:'Select a male and a female.'};let result,threshold,required;const types=[x.breed,y.breed];if(types.every(t=>['Good yellow','Great yellow'].includes(t))){result='Blue or green';threshold=4;required='Carob';}else if(types.includes('Blue')&&types.includes('Green')){result='Black';threshold=9;required='Carob';}else if(types.includes('Black')&&types.includes('Wonderful yellow')){result='Gold';threshold=12;required='Zeio';}else return {ok:false,title:'Outside this planner’s standard route.',text:'Use two Good/Great yellows, a blue + green, or a black + Wonderful yellow. Other genetic combinations exist, but are not modeled here.'};if(nut!==required)return {ok:false,title:'Use a '+required+' Nut for this pairing.',text:'This is the standard '+result.toLowerCase()+' breeding combination.'};if(result==='Gold'&&x.breed!=='Black')return {ok:false,title:'Select the black Chocobo as parent 1.',text:'The black-first selection avoids the known gold-breeding ordering bug.'};if(!x.ready||!y.ready)return {ok:false,title:'Wait for both parents to be ready.',text:'Check readiness with Billy. Adults need 3–10 battle wins after mating; newborns need 3–18 before breeding. Fleeing does not count.'};const wins=x.wins+y.wins;return {ok:true,title:result+' pairing · '+wins+' / '+threshold+' combined wins',text:wins>=threshold?'The standard race-win target is met. Save before breeding; blue versus green and the offspring’s sex still matter. This planner checks your records, not the game’s RNG.':'Earn '+(threshold-wins)+' more combined race wins for the standard reliable target. Lower-win breeding can succeed, but do not treat it as assured.'};}
function stableHTML(){return state.stables.map((s,i)=>`<article class="card stable-card"><div class="stable-title"><span class="eyebrow">STALL ${i+1}</span><span class="choco-dot ${s.breed.split(' ')[0].toLowerCase()}"></span></div><label>Name<input data-stable="${i}" data-field="name" aria-label="Stall ${i+1} name" value="${esc(s.name)}" maxlength="40" placeholder="Name your Chocobo"></label><label>Breed / quality<select data-stable="${i}" data-field="breed" aria-label="Stall ${i+1} breed">${['Empty','Good yellow','Great yellow','Wonderful yellow','Blue','Green','Black','Gold'].map(v=>`<option ${s.breed===v?'selected':''}>${v}</option>`).join('')}</select></label><div class="stable-pair"><label>Sex<select data-stable="${i}" data-field="sex" aria-label="Stall ${i+1} sex">${['Unknown','Male','Female'].map(v=>`<option ${s.sex===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Race wins<input type="number" min="0" max="999" data-stable="${i}" data-field="wins" aria-label="Stall ${i+1} wins" value="${s.wins}"></label></div><label class="stable-ready"><input type="checkbox" data-stable="${i}" data-field="ready" aria-label="Stall ${i+1} ready" ${s.ready?'checked':''}> Billy says ready to breed</label></article>`).join('');}
function plannerOptions(){return state.stables.map((s,i)=>`<option value="${i}">Stall ${i+1}${s.name?' · '+esc(s.name):''} · ${esc(s.breed)}</option>`).join('');}
function chocobos(){return `<div class="view-heading"><span class="eyebrow">THE CHOCOBO BREEDER’S HANDBOOK</span><h1>From tracks to the open ocean.</h1><p>A complete standard breeding route, a six-stall journal, and a pairing checker.<br>You record what is in your game; the planner never breeds or releases a Chocobo for you.</p></div><div class="notice"><b>Earliest start:</b> stables open with the Highwind while Tifa leads. Breeding without racing is possible then, but the reliable racing route becomes practical after Cloud returns and Gold Saucer reopens. Start your captures early; you do not have to wait until Disc 3.</div><div class="breed-tree"><div><span class="choco-dot yellow"></span><b>Good / Great × Good / Great</b><small>Carob · 4 combined wins</small></div><span>→</span><div><span class="choco-dot green"></span><span class="choco-dot blue"></span><b>Green × Blue</b><small>Carob · 9 combined wins</small></div><span>→</span><div><span class="choco-dot black"></span><b>Black × Wonderful</b><small>Zeio · 12 wins · black first</small></div><span>→</span><div><span class="choco-dot gold"></span><b>Gold</b><small>Every terrain type</small></div></div><div class="section-heading"><h2>The breeding route</h2><span id="breedProgress">${BREED_STEPS.filter((_,i)=>state.breedingChecks[i]).length} / ${BREED_STEPS.length} complete</span></div><div class="breed-guide">${BREED_STEPS.map(([title,text],i)=>`<label class="step"><input type="checkbox" data-breed-check="${i}" ${state.breedingChecks[i]?'checked':''} aria-label="Breeding: ${esc(title)}"><div><h3><span class="step-no">${String(i+1).padStart(2,'0')}</span>${esc(title)}</h3><p>${esc(text)}</p></div></label>`).join('')}</div><div class="section-heading" style="margin-top:36px"><h2>Your six-stall journal</h2><span>Autosaved · game state entered by you</span></div><div class="stable-grid">${stableHTML()}</div><section class="card pairing-planner"><div class="section-heading"><h2>Check a pairing</h2><span>Standard-route planner</span></div><div class="planner-fields"><label>Parent 1<select id="parentA">${plannerOptions()}</select></label><span>×</span><label>Parent 2<select id="parentB">${plannerOptions().replace('<option value="1">','<option value="1" selected>')}</select></label><label>Nut<select id="breedNut"><option>Carob</option><option>Zeio</option></select></label><button id="checkPair" class="button primary">Check pairing →</button></div><div id="pairResult" role="status" class="notice">Choose two parents from the stable log. Set their sex, wins and readiness first.</div></section><div class="section-heading" style="margin-top:30px"><h2>Your four cave rewards</h2></div><div class="cave-grid">${CAVES.map(([breed,materia,where],i)=>`<label class="card cave-card"><span class="choco-dot ${breed.toLowerCase()}"></span><h3>${esc(materia)}</h3><p>${esc(where)}</p><span><input type="checkbox" data-cave="${i}" ${state.caves[i]?'checked':''}> Cave reward collected</span></label>`).join('')}</div><div class="notice"><b>If breeding stalls:</b> check Billy’s exact quality label, opposite sexes, an empty stall, the right nut, combined wins, and readiness. Win battles to clear cooldowns. Feeding more greens improves racing stats; it does not substitute for race wins. The planner deliberately avoids platform-sensitive RNG manipulation sequences.</div>`;}
function extraView(){return view==='missables'?missables():view==='characters'?characters():chocobos();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.alertChapter){state.chapter=b.dataset.alertChapter;disc=current().disc;missFilter='This chapter';missDisc='All';missQuery='';missHideDone=false;save();nav('missables');}if(b.id==='checkPair'){const r=breedingResult(+$('#parentA').value,+$('#parentB').value,$('#breedNut').value);$('#pairResult').innerHTML='<b>'+esc(r.title)+'</b><p>'+esc(r.text)+'</p>';}});
document.addEventListener('change',e=>{const x=e.target;if(x.dataset.miss){const a=ALERTS.find(a=>a.id===x.dataset.miss);state.missables[a.id]=x.value;if(a.key){state.checks[a.key]=x.value==='done';for(const other of ALERTS)if(other.key===a.key)state.missables[other.id]=x.value;}save();$('#missDone').textContent=ALERTS.filter(a=>missStatus(a)==='done').length;$('#missRows').innerHTML=missableRows();renderAside();}if(x.id==='missFilter'||x.id==='missDisc'||x.id==='missHideDone'){missFilter=$('#missFilter').value;missDisc=$('#missDisc').value;missHideDone=$('#missHideDone').checked;$('#missRows').innerHTML=missableRows();}if(x.dataset.roster){state.roster[x.dataset.roster]=x.checked;save();render();}if(x.hasAttribute('data-breed-check')){state.breedingChecks[x.dataset.breedCheck]=x.checked;save();$('#breedProgress').textContent=BREED_STEPS.filter((_,i)=>state.breedingChecks[i]).length+' / '+BREED_STEPS.length+' complete';}if(x.hasAttribute('data-cave')){state.caves[x.dataset.cave]=x.checked;const m=M.find(m=>m.name===CAVES[+x.dataset.cave][1]);if(m)state.owned[m.id]=x.checked;save();}if(x.hasAttribute('data-stable')){const s=state.stables[+x.dataset.stable],f=x.dataset.field;s[f]=f==='ready'?x.checked:f==='wins'?Math.max(0,Math.min(999,Number(x.value)||0)):x.value;save();if(f==='breed'){const dot=x.closest('.stable-card').querySelector('.choco-dot');dot.className='choco-dot '+s.breed.split(' ')[0].toLowerCase();}const pa=$('#parentA').value,pb=$('#parentB').value;$('#parentA').innerHTML=plannerOptions();$('#parentB').innerHTML=plannerOptions();$('#parentA').value=pa;$('#parentB').value=pb;$('#pairResult').textContent='Stable log updated. Check the selected pairing again.';}});
document.addEventListener('input',e=>{if(e.target.id==='missSearch'){missQuery=e.target.value;$('#missRows').innerHTML=missableRows();}if(e.target.dataset.field==='name'){state.stables[+e.target.dataset.stable].name=e.target.value.slice(0,40);save();}});
const collapsedDetails=new Set();
function detailState(c,i,j){const key=c.id+'-s'+i+'-d'+j;return typeof state.details[key]==='boolean'?state.details[key]:!!state.checks[c.id+'-s'+i];}
function detailedHTML(c,i){const rows=c.details?.[i];if(!rows?.length)return '';return `<details class="navigation-detail" ${collapsedDetails.has(c.id+'-s'+i)?'':'open'} data-detail-group="${c.id}-s${i}"><summary>Detailed directions <span>${rows.length} checkpoints</span></summary><div class="detail-list">${rows.map(([title,text],j)=>`<label class="detail-row"><input type="checkbox" data-detail="${c.id}-s${i}-d${j}" ${detailState(c,i,j)?'checked':''} aria-label="Checkpoint: ${esc(title)}"><div><b>${esc(title)}</b><p>${esc(text)}</p></div></label>`).join('')}</div></details>`;}
function arrivalHTML(c){return c.arrival?.length?`<section class="arrival-guide">${c.arrival.map(([title,text])=>`<h2>${esc(title)}</h2><p>${esc(text)}</p>`).join('')}</section>`:'';}
document.addEventListener('toggle',e=>{if(e.target.dataset.detailGroup){const key=e.target.dataset.detailGroup;if(e.target.open)collapsedDetails.delete(key);else collapsedDetails.add(key);}},true);
document.addEventListener('change',e=>{const key=e.target.dataset.detail;if(!key)return;const match=key.match(/^(c\d+)-s(\d+)-d(\d+)$/);if(!match)return;const c=C.find(c=>c.id===match[1]),i=+match[2],j=+match[3];const rows=c.details[i];const before=rows.map((_,k)=>detailState(c,i,k));rows.forEach((_,k)=>state.details[c.id+'-s'+i+'-d'+k]=before[k]);state.details[key]=e.target.checked;state.checks[c.id+'-s'+i]=rows.every((_,k)=>detailState(c,i,k));save();render();document.querySelector(`[data-detail="${key}"]`)?.focus({preventScroll:true});});
